const KEY='maitreeInstituteV1';
const defaults={
  settings:{name:'Maitree Computers & Multiservices',mobile:'8381030065',address:'Wai (Bazar), Ta. Mahur',email:'',footer:'Bridge to a better world.'},
  students:[],
  inquiries:[],
  courses:[{id:'c1',name:'MS-CIT',fees:4500,duration:'3 Months'},{id:'c2',name:'Tally Prime',fees:5000,duration:'3 Months'},{id:'c3',name:'Advanced Excel',fees:3500,duration:'2 Months'}]
};
let db=JSON.parse(localStorage.getItem(KEY)||'null')||defaults;
db.settings={...defaults.settings,...(db.settings||{})}; db.students=db.students||[]; db.inquiries=db.inquiries||[]; db.courses=db.courses||defaults.courses; db.students.forEach(s=>{s.payments=s.payments||[];s.paid=Number(s.paid||0);s.finalFees=Number(s.finalFees ?? Math.max(0,Number(s.fees||0)-Number(s.discount||0)));});
save(); let chart1,chart2;
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
window.MAITREE_LOGO_DATA_URL='data:image/jpeg;base64,';window.MAITREE_LOGO_BASE64='data:image/jpeg;base64,';
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN')}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function toast(t){let x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function instituteMobile(){return String(db.settings.mobile||'').replace(/\D/g,'')}
function institutePhoneDisplay(){let n=instituteMobile(); return n.length===10?'+91 '+n.slice(0,5)+' '+n.slice(5):db.settings.mobile||''}
function todayISO(){return new Date().toISOString().slice(0,10)}
function formatDate(v){if(!v)return '-';let d=new Date(v+'T00:00:00');return isNaN(d)?v:d.toLocaleDateString('en-IN',{day:'2-digit',month:'2-digit',year:'numeric'})}
const pages={dashboard:['Dashboard','Institute overview and monthly registrations'],students:['Students','Manage registrations and export records'],registration:['New Registration','Add a student and payment details'],inquiries:['Inquiries','Track prospective students and follow-ups'],courses:['Courses','Manage your institute courses'],fees:['Fees','Payment collection and pending fees'],settings:['Institute Details','Manage institute information shown on receipts and Excel exports']};
function go(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===p));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.getElementById('pageTitle').textContent=pages[p][0];document.getElementById('pageSub').textContent=pages[p][1];if(p==='dashboard')renderDashboard();if(p==='students')renderStudents();if(p==='inquiries')renderInquiries();if(p==='courses')renderCourses();if(p==='fees')renderFees();if(p==='settings')loadSettings();window.scrollTo(0,0);document.querySelector('.sidebar')?.classList.remove('open')}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>go(b.dataset.page));document.addEventListener('click',e=>{let g=e.target.closest('[data-go]');if(g)go(g.dataset.go)});document.getElementById('mobileMenu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.getElementById('today').textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
function nextId(){let y=new Date().getFullYear();let max=db.students.reduce((m,s)=>Math.max(m,parseInt(String(s.id).split('-').pop())||0),0);return `MCI-${y}-${String(max+1).padStart(4,'0')}`}
function fillCourses(){sCourse.innerHTML='<option value="">Select course</option>'+db.courses.map(c=>`<option value="${esc(c.name)}" data-fees="${c.fees}">${esc(c.name)}</option>`).join('')}
sCourse.onchange=()=>{let o=sCourse.selectedOptions[0];if(o&&o.dataset.fees)sFees.value=o.dataset.fees};sDate.value=todayISO();fillCourses();
studentForm.onsubmit=e=>{e.preventDefault();let fees=+sFees.value||0,discount=+sDiscount.value||0,final=Math.max(0,fees-discount),paid=+sPaid.value||0;if(paid>final)return toast('Initial payment cannot exceed final fees');let old=editId.value?db.students.find(x=>x.id===editId.value):null;let payments=old?.payments||[];if(!old&&paid>0)payments=[{id:crypto.randomUUID(),date:sDate.value,amount:paid,mode:sMode.value}];let obj={id:editId.value||nextId(),name:sName.value.trim(),mobile:sMobile.value.trim(),address:sAddress.value.trim(),course:sCourse.value,fees,discount,finalFees:final,paid:old?old.paid:paid,payments,date:sDate.value,notes:sNotes.value.trim()};if(old){obj.paid=payments.reduce((a,p)=>a+Number(p.amount||0),0);if(obj.paid>final)return toast('Final fees cannot be lower than already paid amount');db.students[db.students.findIndex(x=>x.id===old.id)]=obj;toast('Student updated')}else{db.students.push(obj);toast('Student registered: '+obj.id)}save();studentForm.reset();editId.value='';sDate.value=todayISO();sDiscount.value=0;sPaid.value=0;saveStudent.textContent='Add Student';fillCourses();go('students');if(!old)setTimeout(()=>{if(confirm('Student registered successfully. Would you like to print the welcome page now?'))printWelcome(obj.id)},150)};
function renderDashboard(){let now=new Date(),labels=[],vals=[];for(let i=11;i>=0;i--){let d=new Date(now.getFullYear(),now.getMonth()-i,1);labels.push(d.toLocaleDateString('en-IN',{month:'short'}));vals.push(db.students.filter(s=>{let x=new Date(s.date);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()}).length)}statStudents.textContent=db.students.length;statMonth.textContent=vals[11]||0;statInquiries.textContent=db.inquiries.length;statPending.textContent=money(db.students.reduce((a,s)=>a+(s.finalFees-(s.paid||0)),0));let ctx=document.getElementById('registrationChart');if(chart1)chart1.destroy();chart1=new Chart(ctx,{type:'bar',data:{labels,datasets:[{label:'Students',data:vals,borderWidth:1,borderRadius:5}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});let cm=db.courses.map(c=>c.name),cv=cm.map(c=>db.students.filter(s=>s.course===c).length);let ctx2=document.getElementById('courseChart');if(chart2)chart2.destroy();chart2=new Chart(ctx2,{type:'doughnut',data:{labels:cm.length?cm:['No students'],datasets:[{data:cm.length?cv:[1]}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});let recent=[...db.students].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);recentStudents.innerHTML=recent.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Course</th><th>Fees</th><th>Paid</th><th>Pending</th></tr></thead><tbody>${recent.map(s=>`<tr><td>${esc(s.id)}</td><td><strong>${esc(s.name)}</strong></td><td>${esc(s.course)}</td><td>${money(s.finalFees)}</td><td>${money(s.paid)}</td><td>${money(s.finalFees-s.paid)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No registrations yet.</p>'}
function renderStudents(){let q=(studentSearch.value||'').toLowerCase();let a=db.students.filter(s=>(s.name+' '+s.mobile+' '+s.course+' '+s.id).toLowerCase().includes(q)).sort((x,y)=>String(y.date||'').localeCompare(String(x.date||''))||String(y.id).localeCompare(String(x.id)));if(!a.length){studentTable.innerHTML='<tr><td colspan="9">No students found.</td></tr>';return}let groups={};a.forEach(s=>{let d=new Date((s.date||todayISO())+'T00:00:00');let key=d.toLocaleDateString('en-IN',{month:'long',year:'numeric'});(groups[key] ||= []).push(s)});studentTable.innerHTML=Object.entries(groups).map(([month,students])=>`<tr class="month-divider"><td colspan="9">${esc(month)} <span>(${students.length} registration${students.length===1?'':'s'})</span></td></tr>${students.map(s=>`<tr><td>${esc(s.id)}</td><td><strong>${esc(s.name)}</strong></td><td>${esc(s.mobile)}</td><td>${esc(s.course)}</td><td>${money(s.finalFees)}</td><td>${money(s.paid)}</td><td>${money(s.finalFees-s.paid)}</td><td>${formatDate(s.date)}</td><td><button class="action-btn" onclick="viewStudent('${s.id}')">View</button><button class="action-btn receipt" onclick="printReceipt('${s.id}')">Receipt</button><button class="action-btn" onclick="printWelcome('${s.id}')">Welcome</button><button class="action-btn" onclick="editStudent('${s.id}')">Edit</button><button class="action-btn danger" onclick="deleteStudent('${s.id}')">Delete</button></td></tr>`).join('')}`).join('')}
studentSearch.oninput=renderStudents;
function editStudent(id){let s=db.students.find(x=>x.id===id);if(!s)return;go('registration');editId.value=s.id;sName.value=s.name;sMobile.value=s.mobile;sAddress.value=s.address;sDate.value=s.date;sFees.value=s.fees;sDiscount.value=s.discount;sPaid.value=s.paid;sNotes.value=s.notes||'';fillCourses();sCourse.value=s.course;saveStudent.textContent='Update Student'}
function deleteStudent(id){if(!confirm('Delete this student?'))return;db.students=db.students.filter(s=>s.id!==id);save();renderStudents();toast('Student deleted')}
function viewStudent(id){let s=db.students.find(x=>x.id===id);if(!s)return;modalContent.innerHTML=`<h2>${esc(s.name)}</h2><p><b>Student ID:</b> ${esc(s.id)}<br><b>Mobile:</b> ${esc(s.mobile)}<br><b>Address:</b> ${esc(s.address||'-')}<br><b>Course:</b> ${esc(s.course)}<br><b>Registration:</b> ${formatDate(s.date)}</p><hr><p><b>Total Fees:</b> ${money(s.finalFees)} &nbsp; <b>Paid:</b> ${money(s.paid)} &nbsp; <b>Pending:</b> ${money(s.finalFees-s.paid)}</p><h3>Installment / Payment History</h3>${s.payments?.length?`<table><thead><tr><th>Date</th><th>Amount</th><th>Mode</th><th>Receipt</th></tr></thead><tbody>${s.payments.map(p=>`<tr><td>${formatDate(p.date)}</td><td>${money(p.amount)}</td><td>${esc(p.mode)}</td><td><button class="action-btn receipt" onclick="printReceipt('${s.id}','${p.id}')">Print</button></td></tr>`).join('')}</tbody></table>`:'<p>No payments recorded.</p>'}<div class="form-actions"><button class="btn" onclick="addPayment('${s.id}')">＋ Add Payment</button><button class="btn wa" onclick="whatsapp('${s.mobile}','Hello ${esc(s.name)}, this is Maitree Computer Institute. Your pending fee is ${money(s.finalFees-s.paid)}. Please contact us for details.')">WhatsApp</button><button class="btn receipt" onclick="printReceipt('${s.id}')">Print Latest Receipt</button></div>`;modal.classList.remove('hidden')}
function addPayment(id){let s=db.students.find(x=>x.id===id);if(!s)return;let pending=s.finalFees-s.paid;if(pending<=0)return toast('All fees are already paid');let amount=+prompt(`Pending fee: ${money(pending)}\nEnter payment amount (₹):`,pending);if(!amount||amount<=0)return;if(amount>pending)return toast('Payment cannot exceed pending fee');let mode=prompt('Payment mode: Cash / UPI / Bank Transfer','Cash')||'Cash';let date=prompt('Payment date (YYYY-MM-DD):',todayISO())||todayISO();let p={id:crypto.randomUUID(),date,amount,mode};s.payments.push(p);s.paid=s.payments.reduce((a,x)=>a+Number(x.amount||0),0);save();viewStudent(id);toast('Payment added');setTimeout(()=>printReceipt(id,p.id),250)}
function whatsapp(num,msg){let clean=String(num).replace(/\D/g,'');if(clean.length===10)clean='91'+clean;window.open('https://wa.me/'+clean+'?text='+encodeURIComponent(msg),'_blank')}
function renderInquiries(){inquiryTable.innerHTML=db.inquiries.length?db.inquiries.map(i=>`<tr><td><strong>${esc(i.name)}</strong></td><td>${esc(i.mobile)}</td><td>${esc(i.course||'-')}</td><td>${esc(i.follow||'-')}</td><td><span class="status ${esc(i.status).replaceAll(' ','-')}">${esc(i.status)}</span></td><td><button class="action-btn wa" onclick="whatsapp('${i.mobile}','Hello ${esc(i.name)}, this is Maitree Computer Institute. Thank you for your inquiry. How can we help you?')">WhatsApp</button><button class="action-btn danger" onclick="deleteInquiry('${i.id}')">Delete</button></td></tr>`).join(''):'<tr><td colspan="6">No inquiries yet.</td></tr>'}
newInquiryBtn.onclick=()=>inquiryFormWrap.classList.remove('hidden');cancelInquiry.onclick=()=>inquiryFormWrap.classList.add('hidden');inquiryForm.onsubmit=e=>{e.preventDefault();db.inquiries.push({id:crypto.randomUUID(),name:iName.value.trim(),mobile:iMobile.value.trim(),address:iAddress.value.trim(),course:iCourse.value.trim(),follow:iFollow.value,status:iStatus.value,notes:iNotes.value.trim(),date:todayISO()});save();inquiryForm.reset();inquiryFormWrap.classList.add('hidden');renderInquiries();toast('Inquiry saved')};function deleteInquiry(id){if(confirm('Delete this inquiry?')){db.inquiries=db.inquiries.filter(i=>i.id!==id);save();renderInquiries()}}
function renderCourses(){courseTable.innerHTML=db.courses.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${money(c.fees)}</td><td>${esc(c.duration)}</td><td><button class="action-btn danger" onclick="deleteCourse('${c.id}')">Delete</button></td></tr>`).join('')}
addCourseBtn.onclick=()=>{let name=prompt('Course name');if(!name)return;let fees=+prompt('Standard fees (₹)','0');let duration=prompt('Duration','3 Months')||'';db.courses.push({id:crypto.randomUUID(),name,fees:fees||0,duration});save();fillCourses();renderCourses();toast('Course added')};function deleteCourse(id){if(confirm('Delete course?')){db.courses=db.courses.filter(c=>c.id!==id);save();fillCourses();renderCourses()}}
function renderFees(){let total=db.students.reduce((a,s)=>a+s.finalFees,0),paid=db.students.reduce((a,s)=>a+s.paid,0);feeTotal.textContent=money(total);feeCollected.textContent=money(paid);feeDue.textContent=money(total-paid);feeTable.innerHTML=db.students.filter(s=>s.finalFees>s.paid).map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.course)}</td><td>${money(s.finalFees)}</td><td>${money(s.paid)}</td><td>${money(s.finalFees-s.paid)}</td><td><button class="action-btn wa" onclick="whatsapp('${s.mobile}','Hello ${esc(s.name)}, this is Maitree Computer Institute. Your pending fee is ${money(s.finalFees-s.paid)}. Kindly pay your pending amount. Thank you.')">WhatsApp</button></td></tr>`).join('')||'<tr><td colspan="6">No pending fees 🎉</td></tr>'}
async function exportStudents(){try{if(typeof ExcelJS==='undefined')return toast('Excel library is not loaded. Check your internet connection and try again.');let rows=[...db.students].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.id).localeCompare(String(a.id)));let wb=new ExcelJS.Workbook();wb.creator=db.settings.name;wb.created=new Date();let ws=wb.addWorksheet('Students',{views:[{state:'frozen',ySplit:6}]});let logoId;try{logoId=wb.addImage({base64:window.MAITREE_LOGO_BASE64,extension:'jpeg'})}catch(e){};ws.mergeCells('A1:J4');ws.getCell('A1').value=db.settings.name;ws.getCell('A1').font={name:'Arial',size:18,bold:true};ws.getCell('A1').alignment={vertical:'middle',horizontal:'center'};ws.getCell('A1').fill={type:'pattern',pattern:'solid',fgColor:{argb:'EAF0FF'}};if(logoId!==undefined)ws.addImage(logoId,{tl:{col:0,row:0},ext:{width:105,height:105}});ws.mergeCells('A5:J5');ws.getCell('A5').value=`Mobile: ${institutePhoneDisplay()} | ${db.settings.address||''}${db.settings.email?' | Email: '+db.settings.email:''}`;ws.getCell('A5').font={bold:true,size:11};ws.getCell('A5').alignment={horizontal:'center'};let headers=['Student ID','Student Name','Mobile','Address','Course','Total Fees','Discount','Paid Fees','Remaining Fees','Registration Date'];headers.forEach((h,i)=>{let c=ws.getCell(6,i+1);c.value=h;c.font={bold:true,color:{argb:'FFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'1F4E78'}};c.alignment={horizontal:'center',vertical:'middle',wrapText:true}});rows.forEach((st,r)=>{let vals=[st.id,st.name,st.mobile,st.address||'',st.course,Number(st.finalFees||0),Number(st.discount||0),Number(st.paid||0),Math.max(0,Number(st.finalFees||0)-Number(st.paid||0)),st.date||''];vals.forEach((v,c)=>{let cell=ws.getCell(r+7,c+1);cell.value=v;if(c>=5&&c<=8)cell.numFmt='₹#,##0';});});[16,24,15,30,22,14,12,14,17,18].forEach((w,i)=>ws.getColumn(i+1).width=w);ws.autoFilter={from:'A6',to:'J'+Math.max(6,rows.length+6)};ws.getRow(1).height=30;ws.getRow(6).height=30;let blob=await wb.xlsx.writeBuffer();let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([blob],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));a.download='Maitree_Computer_Institute_Students.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Excel exported successfully')}catch(err){console.error(err);toast('Excel export failed. Please try again.')}}
document.getElementById('exportStudentsBtn').addEventListener('click',exportStudents);
function loadSettings(){instName.value=db.settings.name;instMobile.value=db.settings.mobile;instAddress.value=db.settings.address||'';instEmail.value=db.settings.email;instFooter.value=db.settings.footer}
settingsForm.onsubmit=e=>{e.preventDefault();db.settings={name:instName.value.trim(),mobile:instMobile.value.trim(),address:instAddress.value.trim(),email:instEmail.value.trim(),footer:instFooter.value.trim()};save();toast('Institute details saved')};
function receiptHTML(s,p){let payment=p||s.payments?.[s.payments.length-1]||{id:'',date:s.date,amount:s.paid||0,mode:'-'};let remaining=Math.max(0,s.finalFees-s.paid);return `<!doctype html><html><head><meta charset="utf-8"><title>Payment Receipt - ${esc(s.id)}</title><style>@page{size:A4 portrait;margin:0}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#111}.receipt{width:210mm;height:148mm;padding:6mm 9mm;border:1px solid #222;position:relative;overflow:hidden}.head{display:flex;align-items:center;gap:6mm;border-bottom:1px solid #222;padding-bottom:3mm}.head img{width:30mm;height:30mm;object-fit:contain}.top{flex:1;text-align:center}.top h1{font-size:18px;margin:0 0 1mm;text-transform:uppercase}.top p{margin:1mm 0;font-size:10px}.title{text-align:center;font-weight:700;font-size:14px;margin:2mm 0 3mm;text-decoration:underline}.meta{display:flex;justify-content:space-between;font-size:10px;margin-bottom:3mm}.info{width:100%;border-collapse:collapse;font-size:10px;margin-bottom:3mm}.info td{border:1px solid #444;padding:2mm}.info td:first-child,.info td:nth-child(3){font-weight:700;width:18%}.amount{width:100%;border-collapse:collapse;font-size:10px;margin-bottom:4mm}.amount th,.amount td{border:1px solid #444;padding:2mm;text-align:left}.amount th{font-weight:700}.sign{display:flex;justify-content:space-between;align-items:flex-end;margin-top:7mm;font-size:10px}.sigbox{width:55mm;text-align:center;border-top:1px solid #222;padding-top:1.5mm}.footer{text-align:center;font-size:8px;margin-top:3mm;color:#444}</style></head><body><div class="receipt"><div class="head"><img src="${window.MAITREE_LOGO_DATA_URL}" alt="Logo"><div class="top"><h1>${esc(db.settings.name)}</h1><p>${esc(db.settings.address||'')}</p><p>Mobile: ${esc(institutePhoneDisplay())}${db.settings.email?' &nbsp; | &nbsp; Email: '+esc(db.settings.email):''}</p></div></div><div class="title">PAYMENT RECEIPT</div><div class="meta"><span><b>Receipt No:</b> ${esc(s.id)}-${esc(payment.id?payment.id.slice(0,6).toUpperCase():'001')}</span><span><b>Date:</b> ${esc(formatDate(payment.date))}</span></div><table class="info"><tr><td>Student Name</td><td>${esc(s.name)}</td><td>Course</td><td>${esc(s.course)}</td></tr><tr><td>Address</td><td colspan="3">${esc(s.address||'-')}</td></tr></table><table class="amount"><tr><th>Total Fees</th><th>Discount</th><th>Paid Fees</th><th>Remaining Fees</th><th>Payment Mode</th></tr><tr><td>${money(s.fees||s.finalFees)}</td><td>${money(s.discount)}</td><td>${money(s.paid)}</td><td>${remaining?money(remaining):'₹0'}</td><td>${esc(payment.mode||'-')}</td></tr></table><div class="sign"><div class="sigbox">Student Signature</div><div class="sigbox">Institute Head Signature</div></div><div class="footer">${esc(db.settings.footer||'Thank you.')}</div></div><script>window.onload=()=>{window.print();setTimeout(()=>window.close(),500)};<\/script></body></html>`}

function printWelcome(id){let s=db.students.find(x=>x.id===id);if(!s)return;let w=window.open('','_blank','width=900,height=900');if(!w)return toast('Please allow pop-ups to print the welcome page');w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Welcome - ${esc(s.name)}</title><style>@page{size:A4 portrait;margin:12mm}body{font-family:Georgia,serif;margin:0;color:#17233c}.page{min-height:270mm;border:2px solid #1f4e78;padding:18mm;position:relative;text-align:center}.logo{width:45mm;height:45mm;object-fit:contain}.title{font-size:30px;font-weight:700;margin:12mm 0 4mm}.name{font-size:28px;font-weight:700;margin:8mm 0;color:#1f4e78}.course{font-size:18px;margin:5mm}.details{font-family:Arial,sans-serif;font-size:13px;line-height:1.8;margin:10mm auto;max-width:150mm}.message{font-size:17px;line-height:1.7;margin:12mm auto;max-width:155mm}.footer{position:absolute;bottom:12mm;left:15mm;right:15mm;font-family:Arial,sans-serif;font-size:11px}.sign{position:absolute;bottom:30mm;right:20mm;font-family:Arial,sans-serif;font-size:11px;border-top:1px solid #333;padding-top:2mm;width:45mm}</style></head><body><div class="page"><img class="logo" src="${window.MAITREE_LOGO_DATA_URL}"><div class="title">WELCOME TO ${esc(db.settings.name).toUpperCase()}</div><div class="name">${esc(s.name)}</div><div class="course">We are delighted to welcome you for <b>${esc(s.course)}</b>.</div><div class="details"><b>Student ID:</b> ${esc(s.id)}<br><b>Registration Date:</b> ${esc(formatDate(s.date))}<br><b>Mobile:</b> ${esc(s.mobile)}<br><b>Institute:</b> ${esc(db.settings.address||'')}</div><div class="message">Congratulations on your admission!<br>We wish you a successful learning journey and hope your time with us is rewarding and enjoyable.</div><div class="sign">Institute Head</div><div class="footer">${esc(db.settings.footer||'Bridge to a better world.')}<br>Mobile: ${esc(institutePhoneDisplay())}${db.settings.email?' | Email: '+esc(db.settings.email):''}</div></div><script>window.onload=()=>{window.print();setTimeout(()=>window.close(),500)};<\/script></body></html>`);w.document.close()}
function printReceipt(id,paymentId){let s=db.students.find(x=>x.id===id);if(!s)return;let p=paymentId?s.payments.find(x=>x.id===paymentId):null;let w=window.open('','_blank','width=900,height=700');if(!w)return toast('Please allow pop-ups to print the receipt');w.document.open();w.document.write(receiptHTML(s,p));w.document.close()}
backupBtn.onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='Maitree_Backup.json';a.click();URL.revokeObjectURL(a.href)};restoreBtn.onclick=()=>restoreFile.click();restoreFile.onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save();location.reload()}catch{alert('Invalid backup file')}};r.readAsText(f)};
closeModal.onclick=()=>modal.classList.add('hidden');modal.onclick=e=>{if(e.target===modal)modal.classList.add('hidden')};
renderDashboard();
